#ifndef ED_PLATFORM_H
#define ED_PLATFORM_H
/* Edit these pins to match the labels configured in the Minecraft board UI.
 * Drivers are independent projects: SEG=P2 conflicts with KEY9=P2.0.
 * DS1302 uses P3.0/P3.1/P3.2, so do not enable UART on those pins.
 * Timing examples use 12 MHz / 12T. Change ED_FOSC_HZ with the installed crystal.
 */
#ifndef ED_FOSC_HZ
#define ED_FOSC_HZ 12000000UL
#endif
#ifdef __SDCC
__sfr __at(0x80) P0; __sfr __at(0x90) P1;
__sfr __at(0xA0) P2; __sfr __at(0xB0) P3;
__sfr __at(0x88) TCON; __sfr __at(0x89) TMOD;
__sfr __at(0x8A) TL0; __sfr __at(0x8C) TH0;
__sbit __at(0x8C) TR0; __sbit __at(0x8D) TF0; __sbit __at(0xA9) ET0;
__sbit __at(0x96) ED_SDA; __sbit __at(0x97) ED_SCL;
__sbit __at(0x90) ED_LED; __sbit __at(0xA0) ED_KEY9;
__sbit __at(0x92) ED_REDSTONE;
__sbit __at(0xB0) ED_RTC_CE; __sbit __at(0xB1) ED_RTC_CLK; __sbit __at(0xB2) ED_RTC_IO;
__sbit __at(0xB7) ED_DQ;
#define ED_CODE __code
#define ED_IDATA __idata
#define ED_NOP() __asm nop __endasm
#else
#include <REG52.H>
#include <intrins.h>
sbit ED_SDA=P1^6; sbit ED_SCL=P1^7;
sbit ED_LED=P1^0; sbit ED_KEY9=P2^0;
sbit ED_REDSTONE=P1^2;
sbit ED_RTC_CE=P3^0; sbit ED_RTC_CLK=P3^1; sbit ED_RTC_IO=P3^2;
sbit ED_DQ=P3^7;
#define ED_CODE code
#define ED_IDATA idata
#define ED_NOP() _nop_()
#endif
typedef unsigned char ed_u8;
typedef signed char ed_i8;
typedef unsigned int ed_u16;
typedef signed int ed_i16;
typedef unsigned long ed_u32;
typedef signed long ed_i32;
#endif

#ifndef ED_DELAY_H
#define ED_DELAY_H
#include "ed_platform.h"
/* Blocking delay; reserves Timer0, disables ET0, leaves T0 stopped.
 * Setup/call overhead is additional. Do not use this for the initial 1-Wire read edge.
 */
void ed_delay_us(ed_u16 us);
void ed_delay_ms(ed_u16 ms);
#endif

#include "ed_delay.h"
void ed_delay_us(ed_u16 us) {
    ed_u16 ticks,start,part;
    while(us){part=us>10000?10000:us;us-=part;
#if ED_FOSC_HZ == 12000000UL
    ticks=part;
#else
    ticks=(ed_u16)(((ed_u32)part*(ED_FOSC_HZ/12000UL)+999UL)/1000UL);
#endif
    start=0u-ticks; TR0=0; ET0=0; TMOD=(TMOD&0xF0)|1;
    TH0=(ed_u8)(start>>8);TL0=(ed_u8)start;TF0=0;TR0=1;
    while(!TF0) {} TR0=0;
    }
}
void ed_delay_ms(ed_u16 ms) { while(ms--)ed_delay_us(1000); }

#ifndef ED_I2C_BUS_H
#define ED_I2C_BUS_H
#include "ed_platform.h"
/* Seven-bit addresses. Return 1=ACK/success, 0=NACK/failure.
 * Release SDA/SCL with 1; never drive an open-drain bus high via another output.
 */
void ed_i2c_start(void);
void ed_i2c_stop(void);
ed_u8 ed_i2c_write(ed_u8 value);
ed_u8 ed_i2c_read(ed_u8 ack);
ed_u8 ed_i2c_recover(void);
ed_u8 ed_i2c_write_regs(ed_u8 address,ed_u8 reg,const ed_u8 *data,ed_u8 length);
ed_u8 ed_i2c_write_reg(ed_u8 address,ed_u8 reg,ed_u8 value);
ed_u8 ed_i2c_read_regs(ed_u8 address,ed_u8 reg,ed_u8 *data,ed_u8 length);
#endif

#include "i2c_bus.h"
static void pause(void) { ED_NOP();ED_NOP();ED_NOP(); }
void ed_i2c_start(void) { ED_SDA=1;ED_SCL=1;pause();ED_SDA=0;pause();ED_SCL=0; }
void ed_i2c_stop(void) { ED_SDA=0;ED_SCL=1;pause();ED_SDA=1;pause(); }
ed_u8 ed_i2c_write(ed_u8 value) {
    ed_u8 i,ack;
    for(i=0;i<8;i++){ED_SDA=(value&128)!=0;pause();ED_SCL=1;pause();ED_SCL=0;value<<=1;}
    ED_SDA=1;ED_SCL=1;pause();ack=!ED_SDA;ED_SCL=0;return ack;
}
ed_u8 ed_i2c_read(ed_u8 ack) {
    ed_u8 i,value=0;ED_SDA=1;
    for(i=0;i<8;i++){ED_SCL=1;pause();value=(value<<1)|ED_SDA;ED_SCL=0;pause();}
    ED_SDA=!ack;ED_SCL=1;pause();ED_SCL=0;ED_SDA=1;return value;
}
ed_u8 ed_i2c_recover(void) { ed_u8 i;ED_SDA=1;for(i=0;i<9;i++){ED_SCL=0;pause();ED_SCL=1;pause();}ed_i2c_stop();return ED_SDA&&ED_SCL; }
ed_u8 ed_i2c_write_regs(ed_u8 a,ed_u8 reg,const ed_u8 *data,ed_u8 length) {
    ed_u8 i;ed_i2c_start();
    if(!ed_i2c_write(a<<1)||!ed_i2c_write(reg)){ed_i2c_stop();return 0;}
    for(i=0;i<length;i++)if(!ed_i2c_write(data[i])){ed_i2c_stop();return 0;}
    ed_i2c_stop();return 1;
}
ed_u8 ed_i2c_write_reg(ed_u8 a,ed_u8 reg,ed_u8 value){return ed_i2c_write_regs(a,reg,&value,1);}
ed_u8 ed_i2c_read_regs(ed_u8 a,ed_u8 reg,ed_u8 *data,ed_u8 length) {
    ed_u8 i;ed_i2c_start();
    if(!length||!ed_i2c_write(a<<1)||!ed_i2c_write(reg)){ed_i2c_stop();return 0;}
    ed_i2c_start();if(!ed_i2c_write((a<<1)|1)){ed_i2c_stop();return 0;}
    for(i=0;i<length;i++)data[i]=ed_i2c_read(i+1<length);
    ed_i2c_stop();return 1;
}

#ifndef ED_MPU6050_H
#define ED_MPU6050_H
#include "i2c_bus.h"
#define MPU6050_ADDRESS 0x68
typedef struct { ed_i16 ax,ay,az,temperature,gx,gy,gz; } mpu6050_raw;
ed_u8 mpu6050_init(ed_u8 address);
ed_u8 mpu6050_set_ranges(ed_u8 address,ed_u8 gyro_range,ed_u8 accel_range);
ed_u8 mpu6050_read_raw(ed_u8 address,mpu6050_raw *sample);
/* Gyro full-scale code 0: raw / 131 degrees/s. Accel code 0: raw / 16384 g.
 * This is a raw driver, not a DMP/attitude filter. All sample words are big-endian.
 */
#endif

#include "mpu6050.h"
static ed_i16 signed_be(const ed_u8 *p){return (ed_i16)(((ed_u16)p[0]<<8)|p[1]);}
ed_u8 mpu6050_set_ranges(ed_u8 a,ed_u8 gyro,ed_u8 accel) {
    if(gyro>3||accel>3)return 0;
    return ed_i2c_write_reg(a,0x1B,gyro<<3)&&ed_i2c_write_reg(a,0x1C,accel<<3);
}
ed_u8 mpu6050_init(ed_u8 a) {
    ed_u8 id;
    if(!ed_i2c_read_regs(a,0x75,&id,1)||id!=0x68)return 0;
    return ed_i2c_write_reg(a,0x6B,0)&&ed_i2c_write_reg(a,0x1A,3)&&mpu6050_set_ranges(a,0,0);
}
ed_u8 mpu6050_read_raw(ed_u8 a,mpu6050_raw *s) {
    ed_u8 bytes[14];if(!ed_i2c_read_regs(a,0x3B,bytes,14))return 0;
    s->ax=signed_be(bytes);s->ay=signed_be(bytes+2);s->az=signed_be(bytes+4);
    s->temperature=signed_be(bytes+6);s->gx=signed_be(bytes+8);s->gy=signed_be(bytes+10);s->gz=signed_be(bytes+12);return 1;
}

#include "mpu6050.h"
volatile ed_u8 demo_ok,demo_done;
volatile ed_i16 demo_value;
mpu6050_raw sample;
void main(void){
    ED_SDA=ED_SCL=1;
    demo_ok=mpu6050_init(MPU6050_ADDRESS);
    while(1){if(demo_ok&&mpu6050_read_raw(MPU6050_ADDRESS,&sample))demo_value=sample.gx;demo_done=0xA5;}
}

