#ifndef ED_MOTOR_DRIVER_H
#define ED_MOTOR_DRIVER_H
#include "i2c_bus.h"
enum { MOTOR_DOWN=0,MOTOR_UP,MOTOR_NORTH,MOTOR_SOUTH,MOTOR_WEST,MOTOR_EAST };
ed_u8 motor_driver_present(ed_u8 address,ed_u8 *mask);
ed_u8 motor_driver_arm(ed_u8 address,ed_u8 enable);
ed_u8 motor_driver_set_all(ed_u8 address,const ed_i16 rpm[6]);
/* Address 60H..67H; keep sending all channels faster than the 4-tick watchdog.
 * Six little-endian signed words are committed atomically by the final A5H.
 */
#endif

#include "motor_driver.h"
ed_u8 motor_driver_present(ed_u8 a,ed_u8 *mask){ed_u8 p[5];if(!ed_i2c_read_regs(a,0,p,5)||p[0]!=0x4D)return 0;*mask=p[4];return 1;}
ed_u8 motor_driver_arm(ed_u8 a,ed_u8 enable){return ed_i2c_write_reg(a,1,enable?0xA5:0);}
ed_u8 motor_driver_set_all(ed_u8 a,const ed_i16 rpm[6]){
    ed_u8 i;ed_i16 v;ed_i2c_start();
    if(!ed_i2c_write(a<<1)||!ed_i2c_write(0x20)){ed_i2c_stop();return 0;}
    for(i=0;i<6;i++){
        v=rpm[i];if(v>256)v=256;if(v< -256)v=-256;
        if(!ed_i2c_write((ed_u8)v)||!ed_i2c_write((ed_u8)((ed_u16)v>>8))){ed_i2c_stop();return 0;}
    }
    i=ed_i2c_write(0xA5);ed_i2c_stop();return i;
}

#include "motor_driver.h"
volatile ed_u8 demo_ok,demo_done;
volatile ed_i16 demo_value;
/* Read-only demo works without Create. For motion, explicitly arm and keep
 * calling motor_driver_set_all(0x60,rpm) with all six signed channel values.
 */
void main(void){
    ed_u8 mask;ED_SDA=ED_SCL=1;demo_ok=motor_driver_present(0x60,&mask);
    demo_value=mask;demo_done=0xA5;while(1){}
}

#ifndef ED_PCF8591_H
#define ED_PCF8591_H
#include "i2c_bus.h"
/* Address 48H..4FH. mode=0 single-ended, 1/2/3 differential/mixed.
 * Control: bit6 DAC enable, bits5:4 mode, bit2 auto-increment, bits1:0 channel.
 */
ed_u8 pcf8591_read(ed_u8 address,ed_u8 control,ed_u8 *sample);
ed_u8 pcf8591_read_channels(ed_u8 address,ed_u8 *four_samples);
ed_u8 pcf8591_dac(ed_u8 address,ed_u8 control,ed_u8 value);
#endif

#include "pcf8591.h"
static ed_u8 begin_read(ed_u8 a,ed_u8 control){
    ed_i2c_start();if(!ed_i2c_write(a<<1)||!ed_i2c_write(control)){ed_i2c_stop();return 0;}
    ed_i2c_start();if(!ed_i2c_write((a<<1)|1)){ed_i2c_stop();return 0;}return 1;
}
ed_u8 pcf8591_read(ed_u8 a,ed_u8 control,ed_u8 *sample){
    if(!begin_read(a,control))return 0;ed_i2c_read(1); /* discard previous conversion */
    *sample=ed_i2c_read(0);ed_i2c_stop();return 1;
}
ed_u8 pcf8591_read_channels(ed_u8 a,ed_u8 *p){
    ed_u8 i;if(!begin_read(a,0x04))return 0;ed_i2c_read(1);
    for(i=0;i<4;i++)p[i]=ed_i2c_read(i<3);ed_i2c_stop();return 1;
}
ed_u8 pcf8591_dac(ed_u8 a,ed_u8 control,ed_u8 value){
    ed_u8 ok;ed_i2c_start();ok=ed_i2c_write(a<<1)&&ed_i2c_write(control|0x40)&&ed_i2c_write(value);ed_i2c_stop();return ok;
}

#include "pcf8591.h"
volatile ed_u8 demo_ok,demo_done;
volatile ed_i16 demo_value;
void main(void){
    ed_u8 value;ED_SDA=ED_SCL=1;
    while(1){demo_ok=pcf8591_read(0x48,0x40,&value);if(demo_ok){demo_value=value;demo_ok=pcf8591_dac(0x48,0x40,value);}demo_done=0xA5;}
}

